# -*- coding: utf-8 --

from taf.gnb.oam.coam.cu import cu
from taf.rfrl.cbts.utilities import tl_config
from taf.rfrl.cbts.connections.ssh_connections import SSHConnExec
from taf.rfrl.cbts.utilities.generic_utils import get_unique_id_string
from taf.rfrl.cbts.utilities.global_variables import VCU_VERSION_MAPPING
from robot.api import logger

LOG_HEAD = LOG_END = "*" * 8


class GenericCU(object):
    #: The object of taf.gnb.oam.coam.cu
    cu = cu()

    def __init__(self):
        self.rest_connection_store = []
        self.ssh_connection_store = []

    def _get_vcu_version(self, gnb_index=0):
        ssh_connection = SSHConnExec()
        alias = 'vcu get version' + get_unique_id_string()
        vcu_namespace = tl_config.get_vcu_namespace(gnb_index=gnb_index)
        try:
            ssh_connection.connect_to_vcu_cloud_hosting(alias=alias, gnb_index=gnb_index)
            result = ssh_connection.execute_normal_cmd(
                "helm list -n %s | grep aic-vcu-'[0-9]'| awk '{print $9}'" % vcu_namespace, alias=alias)
            vcu_version = '.'.join(result.split('-')[-1].split('.')[:2])
        except Exception:
            return  # if get vcu_version fail will return None. And call connect_to with the default.
        finally:
            ssh_connection.disconnect_vcu_cloud_hosting(alias=alias)
        try:
            return VCU_VERSION_MAPPING[vcu_version]
        except Exception:
            logger.error('The version obtained from OCP is %s, but there is no matching version of taf.gnb.oam.coam.vdu', vcu_version)

    def login_rest(self, webem_username=None, webem_password=None, cu_version=None,
                   gnb_index=0, alias='default', timeout=30):
        """
        Rest login to vcu

        :param str webem_username: vcu webem username, default is None.
                                   If not given, oam_http_connection_details username in testline init file will be used.
        :param str webem_password: vcu webem password, default is None.
                                   If not given, oam_http_connection_details password in testline init file will be used.
        :param str cu_version: identify the taf.gnb.oam.coam.cu interface version, default is None.
                               If not given, the latest version will always be used.
        :param int gnb_index: gnb index in testline init file.
        :param str alias: rest connection alias.
        :param Union[int,str] timeout: (optional) Timeout for rest connection setup, default is 30s.
        :return str: connection alias
        """
        vcu_webem_credentials = tl_config.get_vcu_webem_credentials(gnb_index=gnb_index)
        if not cu_version:
            cu_version = self._get_vcu_version(gnb_index=gnb_index)
        if webem_username:
            username = webem_username
        else:
            username = vcu_webem_credentials['username']
        if webem_password:
            password = webem_password
        else:
            password = vcu_webem_credentials['password']

        if cu_version:
            self.cu.connect_to(host=vcu_webem_credentials['ip'],
                               username=username,
                               password=password,
                               port='',
                               cu_version=cu_version,
                               secure=True,
                               alias=alias,
                               timeout=timeout)
        else:
            self.cu.connect_to(host=vcu_webem_credentials['ip'],
                               username=username,
                               password=password,
                               port='',
                               secure=True,
                               alias=alias,
                               timeout=timeout)

        self.rest_connection_store.append(alias)
        return alias

    def logout_rest(self, conn_alias='default'):
        """
        disconnect the vcu rest login by the given connection alias.

        :param str conn_alias: connection alias, default value is 'default'.
        :return: None
        """
        try:
            self.cu.disconnect(connection=conn_alias)
            self.rest_connection_store.remove(conn_alias)
        except Exception:
            logger.error("{} vcu Rest connection Already disconnected, no need to disconnect it once again {}".format(LOG_HEAD, LOG_END))

    def logout_all_cu_rest(self):
        """
        disconnect all of the vdu rest connection.
        """
        for connection in self.rest_connection_store:
            try:
                self.cu.disconnect(connection=connection)
                self.rest_connection_store.remove(connection)
            except Exception:
                continue
